ALTER TABLE public.merchant_store_memberships ADD COLUMN authorization_approved boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.merchant_store_memberships.authorization_approved IS 'Independent explicit operational authorization; financial linkage or a backfilled membership never approves access.';
CREATE OR REPLACE FUNCTION public.can_actor_manage_marca_store(p_actor uuid,p_store_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p_actor IS NOT NULL AND(p_actor=p_store_id OR EXISTS(SELECT 1 FROM merchant_store_memberships m JOIN brand_account_owned_stores o ON o.store_profile_id=m.store_id JOIN brand_accounts b ON b.id=o.brand_account_id JOIN brand_account_owned_stores p ON p.brand_account_id=b.id AND p.slot=1 AND p.store_role='primary' AND p.store_profile_id=b.owner_profile_id JOIN profiles profile ON profile.id=m.store_id WHERE m.user_id=p_actor AND m.store_id=p_store_id AND m.active AND m.authorization_approved AND m.permission='administrator' AND b.owner_profile_id=p_actor AND profile.deleted_at IS NULL AND coalesce(profile.account_status,'active')='active' AND get_effective_store_plan(b.owner_profile_id)->>'plan'='marca' AND get_effective_store_plan(b.owner_profile_id)->>'planSource'='direct')) $$;
CREATE OR REPLACE FUNCTION public.admin_set_marca_store_membership(p_user_id uuid,p_store_id uuid,p_active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM assert_caller_is_admin();IF NOT EXISTS(SELECT 1 FROM brand_accounts b JOIN brand_account_owned_stores o ON o.brand_account_id=b.id WHERE b.owner_profile_id=p_user_id AND o.store_profile_id=p_store_id) THEN RAISE EXCEPTION 'store_access_denied' USING ERRCODE='42501'; END IF;INSERT INTO merchant_store_memberships(user_id,store_id,active,authorization_approved,created_by) VALUES(p_user_id,p_store_id,p_active,p_active,auth.uid()) ON CONFLICT(user_id,store_id) DO UPDATE SET active=excluded.active,authorization_approved=excluded.authorization_approved,created_by=excluded.created_by;END $$;
CREATE OR REPLACE VIEW public.merchant_store_profiles AS SELECT id,store_name,store_slug,store_description,store_logo_url,primary_color,secondary_color,address,address_city,address_state,address_number,address_neighborhood,address_complement,address_zip_code,phone,whatsapp_number,email,about_us_text,about_us_title,return_policy_text,instagram_url,facebook_url,youtube_url,x_url,banner_desktop_url,banner_mobile_url,banner_desktop_urls,banner_mobile_urls,content_banners,main_banner_content,footer_bg_color,footer_text_color,font_family,font_weight,product_image_format,product_border_style,product_text_alignment,product_button_display,button_border_style,button_bg_color,button_text_color,header_logo_position,price_color,title_color,topbar_enabled,topbar_bg_color,topbar_text_color,topbar_text,topbar_link_type,topbar_link_target,store_model,store_layout,selected_benefit_banners,home_video_enabled,home_video_id,home_video_title,home_video_description,home_video_url_original,is_maintenance_mode,source_template_id,banner_rect_1_url,banner_rect_2_url,minibanner_1_img2_url,minibanner_2_img2_url,content_banner_enabled,content_banner_title,content_banner_subtitle,content_banner_title_color,content_banner_subtitle_color,content_banner_url,content_banner_image_url FROM public.profiles WHERE id=public.merchant_request_store_id() AND public.can_actor_manage_marca_store(auth.uid(),id) WITH LOCAL CHECK OPTION;
GRANT UPDATE(banner_rect_1_url,banner_rect_2_url,minibanner_1_img2_url,minibanner_2_img2_url) ON public.merchant_store_profiles TO authenticated;
COMMENT ON VIEW public.merchant_store_profiles IS 'Explicit operational projection only; account identity fields are not delegated, canonical slug/email remain read-only, and legacy banners preserve existing content.';